  const fora = Number(d.gasto_fora) || 0;
  const linhaFora = fora > 0
    ? `\n_+ ${brl(fora)} em engajamento (fora do CPL) · total ${brl(d.gasto_total)}_`
    : '';
  return [
    `- *${rot}*`,
    `Gasto: ${brl(d.gasto)}`,
    `Leads: ${int(d.leads)}`,
    `CPL:   ${brl(d.cpa)}`,
    `CPM ${brl(d.cpm)} · CTR ${pct(d.ctr)} · Conv ${pct(d.conversao)}${linhaFora}${cobertura}`,
