const pct = v => {
  if (v === null || v === undefined || v === '') return '—';   // 0,0% != sem dado
  const s = nf(Number(v) * 100, 1);
  return s === null ? '—' : s + '%';
};
const int = v => { const s = nf(v, 0); return s === null ? '—' : s; };
const dia = v => v ? String(v).slice(0, 10).split('-').reverse().join('/') : '—';

// Um alerta consolidado por conta. Vazio => nada é enviado e o ramo para aqui.
const rows = $input.all().map(i => i.json).filter(r => r.conta_id);
if (!rows.length) return [];

const rotulo = {
  gasto_fora_da_meta:   'GASTO FORA DA META',
  leads_abaixo_da_meta: 'LEADS ABAIXO DA META',
  saldo_acabando:          'SALDO ACABANDO',
  limite_de_gasto_proximo: 'LIMITE DE GASTO DA CONTA ACABANDO',
  gasto_zerado:            'GASTO ZERADO ONTEM',
};

