parameters.query:
insert into ads_alerta_enviado (dia, conta_id, regra, valor)
select current_date, x.conta_id, x.regra, x.valor
from jsonb_to_recordset($1::jsonb) as x(conta_id text, regra text, valor numeric)
on conflict (dia, conta_id, regra) do nothing
returning regra;

